from l22_common import mk, save
Q={}

mk(Q, 51, [55],
 stem="A 48-year-old woman has a 0.6-mm thick melanoma of the arm. What clinical excision margin is recommended?",
 opts=["3 cm","5 cm","0.2 cm","0.5 cm","1 cm"],
 interp="Melanoma ที่แขนหนา 0.6 mm (Breslow &lt; 1 mm เป็น invasive ไม่ใช่ in situ) → ถามขอบตัดทางคลินิกรอบรอยโรคหรือแผล biopsy เดิมสำหรับ wide local excision ต้องใช้ตารางขอบตัดตามความหนา Breslow ซึ่งเป็นตัวกำหนดหลัก ไม่ใช่ขนาดก้อนที่เห็นหรือ Clark level",
 why="ขอบตัดของ primary melanoma กำหนดจาก<b>ความหนา Breslow</b> (วัดจาก granular layer ถึงจุดที่เซลล์มะเร็งลึกที่สุด) เพราะความลึกสัมพันธ์กับโอกาสมี micrometastasis รอบก้อนและการกลับเป็นซ้ำเฉพาะที่ · ตารางมาตรฐาน: <b>in situ 0.5–1 cm · ≤ 1 mm 1 cm · 1–2 mm 1–2 cm · &gt; 2 mm 2 cm</b> โดย NCCN ปัจจุบันใช้ 2 cm เป็นขอบสูงสุดแม้ก้อนหนาเกิน 4 mm · ขอบนี้เป็น<b>ขอบทางคลินิก</b>วัดจากขอบรอยโรคหรือแผล biopsy ขณะผ่าตัด ไม่ใช่ขอบทางพยาธิ และตัดลึกถึงชั้น fascia ของกล้ามเนื้อโดยไม่ต้องเอา fascia ออก · RCT หลายฉบับพบว่าขอบที่กว้างกว่านี้ เช่น 3–5 cm แบบเดิม ไม่เพิ่มอัตรารอดชีวิต แต่เพิ่มความจำเป็นต้องใช้ graft หรือ flap · ก้อน 0.6 mm ที่ไม่มี ulceration เป็น <b>T1a</b> (AJCC 8th: &lt; 0.8 mm ไม่มีแผล) โดยทั่วไปไม่ต้องทำ sentinel lymph node biopsy ส่วน T1b ให้พิจารณาเป็นราย · สไลด์หน้า 55 ตาราง <b>“&lt;1 mm: 1.0 · randomized studies”</b>",
 wrong={
  "A":"ขอบ 3 cm อยู่ในช่องบนสุดของตารางสไลด์ (&gt; 4 mm: 2.0–3.0 cm) ซึ่งเป็นช่องเดียวที่ยังไม่มี randomized study รองรับ และ NCCN ปัจจุบันให้ 2 cm เป็นขอบสูงสุด ก้อน 0.6 mm ใช้เพียง 1 cm · จะถูกถ้าหญิงมี nodular melanoma หนา 6 mm ที่ต้นขา และศัลยแพทย์ยึดตารางสไลด์หน้า 55 ซึ่งให้ขอบได้ถึง 3 cm สำหรับก้อนหนาเกิน 4 mm",
  "B":"ขอบ 5 cm เป็นแนวทางเก่าก่อนมี RCT ซึ่งต่อมาพบว่าขอบที่แคบลงเหลือ 1–2 cm ให้อัตรารอดชีวิตไม่ต่างกัน แต่ลดการต้องปลูกผิวและความพิการได้มาก · ไม่มีสถานการณ์ใดที่แนวทางปัจจุบันแนะนำขอบ 5 cm สำหรับ primary cutaneous melanoma เพราะทั้งตารางสไลด์และ NCCN ให้ขอบสูงสุดไม่เกิน 2–3 cm ไม่ว่าก้อนจะหนาเท่าใด",
  "C":"ขอบ 1–3 mm เป็นขอบของ excisional biopsy เพื่อวินิจฉัยไฝที่สงสัย ให้พยาธิแพทย์วัดความหนาได้ครบก่อนวางแผนตัดกว้าง ไม่ใช่การรักษาขั้นสุดท้ายของ invasive melanoma ที่รู้ความหนาแล้ว · จะถูกถ้าชายมีไฝสีไม่สม่ำเสมอขอบหยักขนาด 8 mm ที่หลังซึ่งยังไม่มีผลชิ้นเนื้อ และแพทย์วางแผนตัดทั้งก้อนเพื่อวินิจฉัยด้วยขอบแคบราว 2 mm",
  "D":"ขอบ 0.5 cm เป็นขอบของ melanoma in situ ซึ่งเซลล์มะเร็งยังอยู่เหนือ basement membrane และไม่มีความหนา Breslow ก้อน 0.6 mm เป็น invasive แล้วจึงต้องได้อย่างน้อย 1 cm · จะถูกถ้าหญิงมี melanoma in situ ขนาดเล็กที่ลำตัวซึ่งไม่ใช่ชนิด lentigo maligna โดยตารางสไลด์ให้ 0.5 cm และ NCCN ให้ 0.5–1 cm"},
 trap="เลข 0.6 mm ใกล้ 0.5 จึงชวนให้จับคู่กับขอบ 0.5 cm ทั้งที่หน่วยต่างกัน (ความหนาเป็น mm ขอบเป็น cm) และ 0.5 cm เป็นของ in situ เท่านั้น · หลักแยก: invasive melanoma ทุกความหนาเริ่มที่ขอบ 1 cm แล้วเพิ่มเป็น 2 cm เมื่อหนาเกิน 2 mm",
 summary=[
  "แกน: ขอบตัด melanoma กำหนดด้วยความหนา Breslow · &lt; 1 mm → ขอบทางคลินิก 1 cm",
  "ตารางสไลด์หน้า 55: in situ 0.5 · &lt; 1 mm 1.0 · 1–2 mm 1.0–2.0 · 2–4 mm 2.0 · &gt; 4 mm 2.0–3.0 cm (ช่องสุดท้ายไม่มี randomized study)",
  "NCCN ปัจจุบัน: in situ 0.5–1 cm · ≤ 1 mm 1 cm · &gt; 1–2 mm 1–2 cm · &gt; 2 mm 2 cm (ขอบสูงสุด 2 cm)",
  "วัดขอบจากขอบรอยโรคหรือแผล biopsy ขณะผ่าตัด · ตัดลึกถึง fascia ของกล้ามเนื้อ",
  "ขอบกว้าง 3–5 cm แบบเก่าไม่เพิ่มการรอดชีวิต แต่เพิ่มการใช้ graft หรือ flap",
  "ไฝที่สงสัยทำ excisional biopsy ขอบ 1–3 mm ก่อน แล้วจึงตัดกว้างตามความหนา",
  "AJCC 8th: T1a &lt; 0.8 mm ไม่มี ulceration · T1b 0.8–1.0 mm หรือ &lt; 0.8 mm มี ulceration → พิจารณา SLNB"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ก้อน 0.6 mm อยู่ช่อง &lt;1 mm ของตารางสไลด์หน้า 55 ซึ่งให้ขอบ 1.0 cm ตรงกับ NCCN 2025 · จุดที่ต่างจาก guideline: ตารางสไลด์ให้ก้อนหนาเกิน 4 mm ได้ 2–3 cm ขณะที่ NCCN ปัจจุบันใช้ 2 cm เป็นขอบสูงสุด และ NCCN ให้ in situ เป็น 0.5–1 cm (lentigo maligna อาจต้องกว้างกว่า 0.5 cm) · ลายมือ “(ไม่ท่)” เหนือตารางน่าจะหมายถึงไม่ต้องท่องทั้งตาราง แต่ช่อง in situ และ &lt;1 mm ออกสอบบ่อยควรจำให้ได้",
 mnemonic="<b>‘Breslow 1-2-2: บางกว่า 1 mm ตัด 1 cm · 1–2 mm ตัด 1–2 cm · เกิน 2 mm ตัด 2 cm’</b>",
 guide="NCCN Clinical Practice Guidelines in Oncology: Melanoma: Cutaneous (2025); AJCC Cancer Staging Manual 8th ed. (2017) — Melanoma of the skin; Sabiston Textbook of Surgery 21st ed. (2022) — Melanoma and cutaneous malignancies",
 variants=[
  "ชาย melanoma หนา 1.5 mm ที่หลัง → ขอบ 1–2 cm เลือกตามตำแหน่งที่ปิดแผลได้ และเสนอ SLNB เพราะเป็น T2",
  "หญิง invasive melanoma ใต้เล็บนิ้วโป้ง → ตัดนิ้วบางส่วนในระดับที่ได้ขอบปลอด ไม่ใช้การวัดขอบเป็นเซนติเมตรแบบผิวราบ",
  "ชาย melanoma หนา 3 mm ที่แก้มชิดเปลือกตาล่าง ตัดขอบ 2 cm ไม่ได้โดยไม่เสียหน้าที่ → ยอมลดขอบเพื่อรักษาโครงสร้าง แต่ต้องได้ขอบทางพยาธิปลอด",
  "หลัง wide excision ก้อน 0.9 mm ด้วยขอบคลินิก 1 cm ผลพยาธิรายงานขอบปลอด 6 mm → ไม่ต้องตัดเพิ่ม เพราะเนื้อเยื่อหดตัวหลังตัดและเกณฑ์คือขอบทางคลินิก"])

mk(Q, 52, [56, 57],
 stem="A 70-year-old man has a basal cell carcinoma near the lower eyelid. The surgeon removes thin layers one at a time, examines frozen sections of all margins with a map, and excises further only where tumor remains. What is this technique?",
 opts=["Curettage and electrodesiccation","Wide local excision","Sentinel lymph node biopsy","Shave biopsy","Mohs micrographic surgery"],
 interp="BCC ใกล้เปลือกตาล่าง ศัลยแพทย์ตัดเนื้อทีละชั้นบาง ๆ ทำ frozen section ดูขอบทุกด้านพร้อมวาดแผนที่ แล้วตัดเพิ่มเฉพาะจุดที่ยังพบมะเร็ง → ถามชื่อเทคนิค ต้องรู้ขั้นตอนเฉพาะของ Mohs คือ ตัดเป็นชั้น ทำแผนที่ ดูขอบทั้งหมด และตัดซ้ำเฉพาะจุด",
 why="<b>Mohs micrographic surgery</b> ตัดก้อนที่เห็นออกพร้อมขอบแคบเป็นชิ้นรูปจานบาง ๆ ตัดเฉียงราว 45° แล้ว<b>แบ่งชิ้นเนื้อเป็นส่วน ทำสีขอบ และวาดแผนที่</b>ให้ตรงกับตำแหน่งบนผิว จากนั้นกดชิ้นเนื้อให้ขอบข้างและก้นอยู่ระนาบเดียวกันแล้วตัด <b>frozen section แนวนอน</b> ทำให้เห็น<b>ขอบทั้งหมดเกือบ 100%</b> ขณะที่การตัดธรรมดาแล้วหั่นแบบ bread-loafing เห็นขอบเพียงส่วนน้อย · ถ้าส่วนใดยังพบมะเร็งก็ตัดเพิ่ม<b>เฉพาะส่วนนั้น</b>ทีละชั้นจนขอบปลอด แล้วจึงเย็บปิดหรือ reconstruct ในวันเดียวกัน · ผลคือ cure rate สูงที่สุดในมะเร็งผิวหนัง (primary BCC ราว 99%) และเก็บเนื้อดีไว้มากที่สุด จึงเหมาะกับตำแหน่งที่ทุกมิลลิเมตรสำคัญ เช่น เปลือกตา จมูก หู ริมฝีปาก รวมถึงก้อนกลับเป็นซ้ำ ขอบไม่ชัด หรือชนิด infiltrative · สไลด์หน้า 57 ลายมือ <b>“ตัดเพิ่มแค่ฝั่งที่ยัง positive จนกว่าจะ free → reconstruct + ปิดแผล”</b>",
 wrong={
  "A":"Curettage and electrodesiccation คือการขูดก้อนเนื้อนุ่มด้วย curette แล้วจี้ไฟฟ้าพื้นแผลสลับขูดซ้ำ 2–3 รอบ ใช้กับ BCC ขนาดเล็กความเสี่ยงต่ำบนลำตัวหรือแขนขา และไม่มีชิ้นเนื้อเหลือให้ตรวจขอบ · จะถูกถ้าชายมี superficial BCC 8 mm ที่หลัง แพทย์ขูดก้อนออกด้วย curette แล้วจี้ไฟฟ้าพื้นแผล สลับขูดและจี้ซ้ำสามรอบ",
  "B":"Wide local excision ตัดก้อนครั้งเดียวด้วยขอบที่กำหนดล่วงหน้า (BCC ความเสี่ยงต่ำ 4 mm) แล้วส่งชิ้นเนื้อตรวจถาวรแบบหั่นเป็นแผ่นซึ่งเห็นขอบเพียงบางส่วน ไม่มีการตัดซ้ำทีละชั้นพร้อมแผนที่ · จะถูกถ้าหญิงมี nodular BCC ขอบชัด 1 cm ที่ต้นแขน แพทย์ตัดเป็นรูปรีด้วยขอบ 4 mm ครั้งเดียว เย็บปิด แล้วส่งพยาธิ",
  "C":"Sentinel lymph node biopsy ฉีดสารกัมมันตรังสีหรือสีรอบก้อนเพื่อหาต่อมน้ำเหลืองต่อมแรกที่รับน้ำเหลือง แล้วตัดต่อมนั้นไปตรวจ เป็นการ staging ไม่ใช่การตัดก้อนที่ผิว และ BCC แทบไม่กระจายทางน้ำเหลือง · จะถูกถ้าหญิงมี melanoma หนา 1.5 mm ที่น่อง ได้ฉีด technetium รอบแผลแล้วตัดต่อมที่ขาหนีบซึ่งจับสารมากที่สุดไปตรวจ",
  "D":"Shave biopsy ใช้มีดเฉือนรอยโรคที่นูนขนานผิวถึงชั้น dermis ครั้งเดียวเพื่อวินิจฉัย ไม่มีการทำแผนที่หรือตัดเพิ่มจนขอบปลอด และไม่เหมาะกับรอยโรคสงสัย melanoma ที่ต้องวัดความหนา · จะถูกถ้าชายมีตุ่มนูนมันวาวสงสัย BCC ที่หน้าผาก แพทย์ฉีดยาชาแล้วเฉือนส่วนนูนออกชิ้นเดียวส่งตรวจเพื่อยืนยันชนิดก่อนวางแผนรักษา"},
 trap="เห็นคำว่า frozen section ดูขอบ อาจนึกถึง wide excision ที่ส่ง frozen ระหว่างผ่าตัด แต่ wide excision ตัดขอบที่กำหนดครั้งเดียวและสุ่มดูขอบบางส่วน · ตัวแยกของ Mohs คือ ตัดเป็นชั้น + แผนที่ + ดูขอบทั้งหมด + ตัดซ้ำเฉพาะจุดที่ยัง positive",
 summary=[
  "แกน: ตัดทีละชั้น + แผนที่ + frozen ดูขอบทั้งหมด + ตัดซ้ำเฉพาะจุดที่ positive = Mohs micrographic surgery",
  "ลายมือหน้า 56: “= ค่อยๆ ตัดทีละ mm” · “กรณีอยู่ใกล้ organ สำคัญ” · หน้า 57: “ใช้กับบนหน้า → ไม่อยากตัดเยอะ”",
  "ขั้นตอนในรูปหน้า 57: ตัดชิ้นรูปจาน → แบ่งส่วนทำสี Red และ Blue → mapping บน index card → section &amp; stain → marking จุดที่ยังมีมะเร็ง",
  "ดูขอบข้างและก้นได้เกือบ 100% ต่างจาก bread-loafing ที่เห็นขอบส่วนน้อย",
  "ข้อบ่งชี้หลัก: BCC และ cSCC ที่ H-zone ของหน้า · ก้อนกลับเป็นซ้ำ · ขอบไม่ชัด · ชนิด infiltrative หรือ morpheaform",
  "Cure rate primary BCC ราว 99% · ปิดแผลหรือ reconstruct ได้ทันทีเมื่อขอบปลอด"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ลายมือสไลด์หน้า 56–57 อธิบายการตัดทีละ mm ทำ frozen และตัดต่อเฉพาะฝั่งที่ positive ตรงกับโจทย์ทุกองค์ประกอบ · ลายมือเขียนว่าคนตัดคือ dermatopathologist ที่นั่งดู แต่ตามมาตรฐานปัจจุบันศัลยแพทย์ Mohs ที่ผ่านการฝึกอ่าน frozen เป็นทั้งผู้ตัดและผู้อ่านสไลด์เอง · สไลด์หน้า 56 ระบุปีพัฒนา 1932 และ fresh-tissue ปี 1970 ขณะที่ตำราส่วนใหญ่ระบุว่าเทคนิค fresh-tissue แพร่หลายหลังรายงานช่วงกลางทศวรรษ 1970 จึงไม่ควรยึดตัวเลขปีในสไลด์เป็นจุดออกสอบ",
 mnemonic="<b>‘Mohs = Map + Only positive side + Horizontal frozen + Spare tissue’</b>",
 guide="NCCN Clinical Practice Guidelines in Oncology: Basal Cell Skin Cancer (2025); AAD/ACMS/ASDSA/ASMS Appropriate Use Criteria for Mohs Micrographic Surgery (J Am Acad Dermatol 2012); Grabb and Smith's Plastic Surgery 8th ed. (2020)",
 variants=[
  "ชาย BCC กลับเป็นซ้ำในแผลเป็นเดิมที่ร่องแก้มจมูกหลังเคยตัดธรรมดา → Mohs เพราะก้อนซ้ำแทรกไปในแผลเป็นตามแนวที่มองไม่เห็น ต้องดูขอบทั้งหมด",
  "หลัง Mohs ที่เปลือกตาล่างได้ขอบปลอด แต่แผลกว้างเกือบครึ่งเปลือกตา → reconstruct ทันที เช่น flap จากแก้ม เพื่อกันหนังตาล่างปลิ้น",
  "ชาย cSCC ความเสี่ยงสูงที่ริมฝีปากล่าง → ใช้ Mohs ได้เช่นกัน ไม่จำกัดเฉพาะ BCC เพราะช่วยเก็บริมฝีปากและได้ขอบที่ตรวจครบ"])

mk(Q, 53, [58],
 stem="A 75-year-old man with a facial basal cell carcinoma is offered Mohs surgery. Which is a disadvantage?",
 opts=["It has a low cure rate","It is slow, costly and needs a specialist","It increases morbidity compared with standard excision","It removes more normal tissue than wide excision","It cannot be used on the face"],
 interp="BCC ที่หน้าซึ่งได้รับข้อเสนอให้ทำ Mohs → ถามข้อเสียของวิธีนี้ ต้องรู้ทั้งข้อดีและข้อเสียตามที่สไลด์แบ่งไว้ แล้วแยกให้ได้ว่าช้อยที่เหลือเป็นข้อดีที่ถูกพลิกกลับ ข้อเสียจริงคือเวลา ค่าใช้จ่าย ความไม่สะดวก และการต้องมีผู้เชี่ยวชาญ",
 why="ข้อเสียของ Mohs มาจาก<b>ขั้นตอนที่ต้องตัดแล้วรอ frozen section ทีละรอบ</b>: แต่ละ stage ใช้เวลาเตรียมและย้อมสไลด์ราว 30–60 นาที ผู้ป่วยต้องนั่งรอโดยมีแผลเปิดอยู่ ก้อนใหญ่หรือขอบไม่ชัดอาจต้อง 2–4 รอบจนใช้เวลาเกือบทั้งวัน (<b>Time · Inconvenience to patient</b>) · ต้องมีห้องปฏิบัติการ frozen ติดห้องผ่าตัด เจ้าหน้าที่เตรียมสไลด์ และ<b>ศัลยแพทย์ที่ผ่านการฝึก Mohs</b> ซึ่งอ่านสไลด์ได้เอง (<b>Require specialist</b>) ทำให้ค่าใช้จ่ายต่อครั้งสูงกว่าการตัดธรรมดา (<b>Cost</b>) และมีให้บริการเฉพาะโรงพยาบาลใหญ่ · ส่วนข้อดีคือ <b>cure rate สูงที่สุด</b> (primary BCC ราว 99% recurrent BCC ราว 94%) <b>เก็บเนื้อดีได้มากที่สุด</b> และ morbidity ต่ำเพราะแผลเล็ก จึงคุ้มกับก้อนที่หน้า แต่ไม่คุ้มกับก้อนเล็กความเสี่ยงต่ำบนลำตัว · สไลด์หน้า 58 <b>“Disadvantage · Time, Cost · Inconvenience to patient · Require specialist”</b>",
 wrong={
  "A":"อัตราหายของ Mohs สูงที่สุดในบรรดาวิธีรักษามะเร็งผิวหนังชนิด keratinocyte คือ primary BCC ราว 99% และ recurrent BCC ราว 94% เพราะเห็นขอบทั้งหมด สไลด์จัด high cure rates ไว้ในข้อดี · ไม่มีสถานการณ์ใดที่อัตราหายต่ำถูกนับเป็นข้อเสียของ Mohs เมื่อเทียบกับการตัดธรรมดา การฉายรังสี หรือการขูดจี้",
  "C":"Mohs ตัดเพิ่มเฉพาะจุดที่ยังมีมะเร็ง แผลจึงเล็กที่สุดเท่าที่ทำได้ ปิดง่าย ทำภายใต้ยาชาเฉพาะที่และกลับบ้านได้ในวันเดียว สไลด์จัด decrease morbidity เป็นข้อดี โดยลายมือให้เหตุผลว่าสูญเสีย tissue น้อย · ไม่มีสถานการณ์ใดที่ Mohs เพิ่ม morbidity เมื่อเทียบกับการตัดธรรมดาที่ต้องเผื่อขอบกว้างเท่ากันรอบด้าน",
  "D":"การตัดธรรมดาต้องเผื่อขอบเท่ากันทุกด้าน (BCC อย่างน้อย 4 mm) แม้ด้านนั้นไม่มีมะเร็ง ส่วน Mohs เริ่มจากขอบแคบ 1–2 mm แล้วขยายเฉพาะจุดที่ positive จึงเป็น significant tissue conservation · ไม่มีสถานการณ์ใดที่ Mohs ตัดเนื้อปกติมากกว่า wide excision ของก้อนเดียวกันเมื่อได้ขอบปลอดเท่ากัน เพราะหลักของวิธีคือเก็บเนื้อดีให้มากที่สุด",
  "E":"ใบหน้าเป็นตำแหน่งหลักที่ใช้ Mohs เพราะทุกมิลลิเมตรมีผลต่อหน้าที่และความสวยงาม เช่น เปลือกตา จมูก หู ริมฝีปาก ซึ่งการตัดเผื่อขอบกว้างจะทำให้เสียรูป · ไม่มีสถานการณ์ใดที่ตำแหน่งบนใบหน้าเป็นข้อห้ามของ Mohs ตรงกันข้าม H-zone ของหน้าเป็นข้อบ่งชี้ที่ชัดที่สุดตามเกณฑ์ appropriate use"},
 trap="ช้อยผิดทุกตัวคือข้อดีของ Mohs ที่ถูกพลิกเป็นตรงข้าม (cure rate สูง morbidity ต่ำ ประหยัดเนื้อเยื่อ ใช้ที่หน้าได้ดี) คนที่จำได้แค่ว่า Mohs ดีจะสับสน · วิธีแยก: ข้อเสียทุกข้อเป็นเรื่องทรัพยากร คือ เวลา เงิน ความสะดวก และผู้เชี่ยวชาญ ไม่ใช่เรื่องผลการรักษา",
 summary=[
  "แกน: ข้อเสีย Mohs = Time · Cost · Inconvenience to patient · Require specialist (สไลด์หน้า 58)",
  "ข้อดี: High cure rates · Decrease morbidity (ลายมือ: ∵ สูญเสีย tissue น้อย) · Significant tissue conservation",
  "แต่ละ stage รอ frozen ราว 30–60 นาที ก้อนใหญ่อาจต้องหลายรอบจนเกือบทั้งวัน",
  "Cure rate: primary BCC ราว 99% · recurrent BCC ราว 94% สูงกว่าการตัดธรรมดา",
  "ต้องมีห้อง frozen ติดห้องผ่าตัดและศัลยแพทย์ที่อ่านสไลด์เอง จึงมีเฉพาะศูนย์ใหญ่",
  "เลือกใช้เมื่อประโยชน์คุ้มต้นทุน: หน้า ก้อนซ้ำ ขอบไม่ชัด · ไม่ใช้กับก้อนเล็กความเสี่ยงต่ำบนลำตัว"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — สไลด์หน้า 58 ระบุข้อเสียไว้ตรงตัวและไฮไลต์ทุกคำ ส่วนช้อยที่เหลือเป็นข้อดีที่ถูกพลิก · ตรงกับ Appropriate Use Criteria ของ AAD ปี 2012 ที่ใช้ความเสี่ยงของก้อนและตำแหน่งเป็นเกณฑ์เลือก Mohs · ข้อสังเกต: เมื่อคิดต้นทุนรวม (ไม่ต้องผ่าซ้ำเพราะขอบไม่ปลอด ไม่ต้องนอนโรงพยาบาล) การศึกษาบางชิ้นพบว่า Mohs ไม่แพงกว่าการตัดธรรมดามากนัก แต่ในบริบทที่ผู้เชี่ยวชาญมีน้อย ข้อจำกัดเรื่องผู้เชี่ยวชาญและเวลายังเป็นจริงเต็มที่",
 mnemonic="<b>‘ข้อเสีย Mohs = TICS: Time · Inconvenience · Cost · Specialist’</b>",
 guide="AAD/ACMS/ASDSA/ASMS Appropriate Use Criteria for Mohs Micrographic Surgery (J Am Acad Dermatol 2012); NCCN Clinical Practice Guidelines in Oncology: Basal Cell Skin Cancer (2025)",
 variants=[
  "ชายอายุ 92 ปีหัวใจล้มเหลว นั่งรอนานไม่ได้ มี BCC ที่ปลายจมูก → ข้อเสียเรื่องเวลาและความไม่สะดวกเด่นที่สุด อาจเลือกตัดธรรมดาหรือฉายรังสีแทน",
  "โรงพยาบาลจังหวัดไม่มีห้อง frozen และศัลยแพทย์ Mohs พบ BCC ขอบไม่ชัดที่หัวตา → ตัดแล้วรอผลขอบจากชิ้นเนื้อถาวรก่อน ค่อย reconstruct เมื่อขอบปลอด หรือส่งต่อ",
  "ชายสุขภาพดีมี nodular BCC 6 mm ที่ต้นขา → Mohs ไม่คุ้มทั้งเวลาและค่าใช้จ่าย ตัดขอบ 4 mm ครั้งเดียวพอ"])

mk(Q, 54, [59, 's6', 's7'],
 stem="A 70-year-old man after a stroke lies motionless on his back. Pressure over the sacrum is about 70 mm Hg. Approximately how long before irreversible tissue damage occurs, and what is the preventive measure?",
 opts=["About 2 hours; turn him every 2 hours","About 1 week; no turning is needed","Damage never occurs below 100 mm Hg, so no action is needed","About 24 hours; turning him once daily is sufficient","About 10 minutes; keep him sitting upright"],
 interp="ผู้ป่วยหลัง stroke ขยับตัวเองไม่ได้ นอนหงายนิ่ง แรงกดที่ก้นกบราว 70 mmHg ซึ่งเกินสองเท่าของความดันปลาย arterial ของหลอดเลือดฝอย (32 mmHg) → ถามระยะเวลาที่เนื้อเยื่อเสียหายถาวรและวิธีป้องกัน ต้องใช้หลักความสัมพันธ์ระหว่างแรงกดกับเวลา",
 why="แรงกดภายนอกที่<b>สูงกว่าความดันในหลอดเลือดฝอย</b> (arteriole 32 · capillary 20 · venule 12 mmHg) ทำให้หลอดเลือดแฟบ เลือดไม่ไหลผ่าน เนื้อเยื่อขาดเลือดเฉพาะที่ และเมื่อปล่อยแรงกดยังเกิด reperfusion injury ซ้ำ · การทดลองคลาสสิกพบว่า<b>แรงกดราว 70 mmHg ต่อเนื่อง 2 ชั่วโมง</b>เริ่มทำให้เนื้อเยื่อเสียหายถาวร และความเสียหายสัมพันธ์แบบผกผันกับเวลา แรงกดยิ่งสูงยิ่งใช้เวลาสั้น ส่วนการกดสลับปล่อยทนได้ดีกว่ามาก · ขณะนอนหงาย sacrum รับแรงได้ถึงราว 150 mmHg ขณะนั่ง ischial tuberosity ถึงราว 300 mmHg คนปกติจึงขยับตัวเองโดยไม่รู้ตัว แต่ผู้ป่วยอัมพาต ไม่รู้สึกตัว หรือชา จะไม่ขยับ · <b>กล้ามเนื้อทนขาดเลือดได้น้อยกว่าผิว</b> เนื้อลึกจึงตายก่อนผิวแตก · การป้องกันคือ<b>พลิกตัวเปลี่ยนท่าเป็นระยะ</b> ร่วมกับที่นอนลดแรงกด ท่าตะแคง 30° และลดแรงเฉือน · สไลด์หน้า 59 ลายมือ <b>“ถ้า P เกิน 2 เท่า ของ capillary arterial end 2 ชม. → irreversible tissue damage ∴ พลิกตัวทุก 2 ชม.”</b>",
 wrong={
  "B":"ระยะ 1 สัปดาห์ยาวกว่าความจริงมาก เนื้อเยื่อที่ถูกกดเกินความดันหลอดเลือดฝอยเริ่มเสียหายถาวรภายในไม่กี่ชั่วโมง และกล้ามเนื้อใต้ผิวตายก่อนที่ผิวจะเปลี่ยนสีให้เห็น · ไม่มีสถานการณ์ใดที่ผู้ป่วยติดเตียงซึ่งขยับตัวเองไม่ได้ถูกปล่อยให้นอนท่าเดิมโดยไม่ต้องพลิกตัว เพราะแม้นอนบนที่นอนลดแรงกดที่ดีที่สุดก็ยังต้องเปลี่ยนท่าเป็นระยะ",
  "C":"ไม่มีเกณฑ์ 100 mmHg ที่ถือว่าปลอดภัย เพราะแรงกดใดที่สูงกว่าความดันปลาย arterial ของหลอดเลือดฝอย 32 mmHg ก็ทำให้เลือดหยุดไหลได้ และราว 65–70 mmHg นาน 2 ชั่วโมงก็เสียหายถาวรแล้ว · ไม่มีสถานการณ์ใดที่แรงกดต่อเนื่องเกินความดันหลอดเลือดฝอยในผู้ป่วยที่ขยับเองไม่ได้ถือว่าปลอดภัยโดยไม่ต้องทำอะไร เพียงเพราะต่ำกว่า 100 mmHg",
  "D":"การพลิกวันละครั้งปล่อยให้แรงกดค้างนานเกือบ 24 ชั่วโมง ซึ่งเกินระยะ 2 ชั่วโมงที่เนื้อเยื่อเริ่มเสียหายถาวรหลายเท่า แผลลึกถึงกล้ามเนื้อจะเกิดก่อนเห็นรอยแดงที่ผิว · ไม่มีสถานการณ์ใดที่การพลิกตัววันละครั้งเพียงพอสำหรับผู้ป่วยที่ขยับเองไม่ได้ แม้ใช้ที่นอนลมแบบ alternating pressure ก็ยังต้องกำหนดรอบพลิกที่ถี่กว่านั้นตามความเสี่ยง",
  "E":"สิบนาทีสั้นเกินจริง และการให้นั่งไม่ได้เอาแรงกดออก เพียงย้ายไปที่ ischial tuberosity ซึ่งขณะนั่งรับแรงได้ถึงราว 300 mmHg สูงกว่าท่านอนหงาย ทั้งยังเพิ่มแรงเฉือนที่ก้นกบเมื่อตัวไถลลง · ไม่มีสถานการณ์ใดที่การให้นั่งนิ่งต่อเนื่องใช้แทนการพลิกตัวได้ เพราะทุกท่าที่ค้างไว้นานล้วนสร้างจุดกดใหม่ ต้องเปลี่ยนท่าเป็นระยะเสมอ"},
 trap="คนมักคิดว่าแผลกดทับต้องใช้แรงกดสูงมากหรือนอนนานเป็นวันจึงเกิด หรือคิดว่าที่นอนดีหรือการให้นั่งแทนการพลิกได้ · หลักแยก: แรงกดแค่สองเท่าของ 32 mmHg นานราว 2 ชั่วโมงก็พอให้เนื้อเยื่อตาย และกล้ามเนื้อตายก่อนผิว จึงพลิกทุก 2 ชั่วโมง",
 summary=[
  "แกน: แรงกด &gt; 2 เท่าของ capillary arterial end (32 → ~65 mmHg) นาน 2 ชม. → irreversible damage → พลิกตัวทุก 2 ชม. (ลายมือหน้า 59)",
  "ความดันในหลอดเลือด (ชีทหน้า 6 + ลายมือหน้า 59): arteriole 32 · capillary 20 · venule 12 mmHg",
  "แรงกดตามท่า: นั่ง ischial tuberosity ~300 mmHg (ชีทหน้า 6) · นอนหงาย sacrum ~150 mmHg (ชีทหน้า 7)",
  "แรงกดกับเวลาผกผันกัน: แรงสูงใช้เวลาน้อย · กดสลับปล่อยทนได้ดีกว่ากดต่อเนื่อง",
  "ชีทหน้า 7: กล้ามเนื้อทนขาดเลือดได้น้อยกว่าผิว → เนื้อลึกตายก่อนผิว · การรักษาที่ดีที่สุดคือป้องกัน",
  "ป้องกันร่วม: ที่นอนลดแรงกด · ตะแคง 30° · ลด shear และความชื้น · คัดกรองด้วย Braden scale"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ลายมือสไลด์หน้า 59 ระบุเกณฑ์สองเท่าของ 32 mmHg (65 mmHg) นาน 2 ชั่วโมง และพลิกตัวทุก 2 ชั่วโมง ตรงกับการทดลองคลาสสิกที่แรงกดราว 70 mmHg นาน 2 ชั่วโมงทำให้เกิดการเปลี่ยนแปลงทางพยาธิ · จุดที่ต่างจาก guideline ปัจจุบัน: EPUAP/NPIAP/PPPIA 2019 ไม่กำหนดตัวเลข 2 ชั่วโมงตายตัว แต่ให้ปรับความถี่การพลิกตามความเสี่ยง สภาพผิว และชนิดที่นอน ตัวเลข 2 ชั่วโมงจึงเป็นค่าตั้งต้นที่ใช้ได้ในข้อสอบและหอผู้ป่วยทั่วไป",
 mnemonic="<b>‘32 × 2 = 65 mmHg × 2 ชม. → พลิกทุก 2 ชม.’</b>",
 guide="EPUAP/NPIAP/PPPIA Prevention and Treatment of Pressure Ulcers/Injuries: Clinical Practice Guideline, 3rd ed. (2019); Grabb and Smith's Plastic Surgery 8th ed. (2020) — Pressure sores",
 variants=[
  "ผู้ป่วยติดเตียงนอนบนที่นอนลมแบบ alternating pressure → ยังต้องพลิกตัวตามรอบ ที่นอนลดแรงกดช่วยยืดเวลาที่ทนได้แต่ไม่แทนการเปลี่ยนท่า",
  "ผู้ป่วยนั่งพิงเตียงที่ยกหัวสูงจนตัวไถลลงปลายเตียง → แรงเฉือนที่ sacrum ทำให้หลอดเลือดลึกบิดขาด ยกส่วนเข่าของเตียงกันไถล และยกหัวเตียงไม่เกิน 30° ถ้าไม่มีข้อบ่งชี้อื่น",
  "ชายบาดเจ็บไขสันหลังระดับอก ชาครึ่งล่าง → ไม่รู้สึกปวดเมื่อถูกกด จึงไม่ขยับตัวเอง ต้องสอนตรวจผิวทุกวันด้วยกระจกและตั้งรอบเปลี่ยนท่า"])

mk(Q, 55, [59, 's6', 's7'],
 stem="A 30-year-old wheelchair user with spinal cord injury sits for many hours each day. Where is a pressure injury most likely to develop?",
 opts=["Over the sacrum","Over the occiput","Over the ischial tuberosities","Over the greater trochanter of the hip","Over the heel"],
 interp="ผู้ใช้รถเข็นจากไขสันหลังบาดเจ็บ นั่งวันละหลายชั่วโมงและมักชาบริเวณก้น → ถามตำแหน่งที่เกิดแผลกดทับบ่อยที่สุดในท่านั่ง ต้องใช้หลักว่าแผลเกิดที่ปุ่มกระดูกซึ่งรับน้ำหนักตัวในท่าที่ผู้ป่วยอยู่นานที่สุด",
 why="แผลกดทับเกิดที่<b>ปุ่มกระดูกที่รับน้ำหนักตัวในท่าที่ค้างอยู่นานที่สุด</b> เพราะเนื้อเยื่อระหว่างกระดูกกับพื้นผิวถูกบีบแน่นที่สุด · ขณะนั่ง น้ำหนักลำตัวลงที่ <b>ischial tuberosities</b> แรงกดสูงได้ถึงราว <b>300 mmHg</b> · ขณะนอนหงายลงที่ <b>sacrum</b> ราว 150 mmHg · ขณะนอนตะแคงลงที่ greater trochanter, lateral malleolus และใบหู · ผู้บาดเจ็บไขสันหลังเสี่ยงสูงสุดเพราะ<b>ไม่มีความรู้สึก</b> จึงไม่รู้ว่าต้องขยับ กล้ามเนื้อก้นลีบจนเหลือเนื้อรองน้อย มีกล้ามเนื้อเกร็ง และผิวเปียกจากการกลั้นอุจจาระปัสสาวะไม่ได้ · ischial pressure injury จึงเป็นแผลหลักของผู้ใช้รถเข็น ต้องใช้เบาะลดแรงกดเฉพาะบุคคล ยกตัวหรือเอนตัวลดแรงกดเป็นระยะ จัดท่านั่งให้ถูก และตรวจผิวทุกวัน · สไลด์หน้า 59 <b>“Sitting position: ischial tuberosities · Supine position: sacral area”</b>",
 wrong={
  "A":"Sacrum เป็นตำแหน่งที่พบแผลกดทับบ่อยที่สุดโดยรวมในผู้ป่วยติดเตียง เพราะรับแรงกดราว 150 mmHg ในท่านอนหงาย แต่ผู้ใช้รถเข็นที่นั่งตัวตรงลงน้ำหนักที่ปุ่มกระดูกก้นนั่ง · จะถูกถ้าชายอายุ 80 ปีนอนหงายติดเตียงหลังเลือดออกในสมอง และพลิกตัวเองไม่ได้เกือบตลอดวัน",
  "B":"ท้ายทอยรับแรงกดมากในทารกและเด็กเล็ก เพราะศีรษะใหญ่และหนักเมื่อเทียบกับลำตัว ส่วนผู้ใหญ่ที่นั่งรถเข็นท้ายทอยแทบไม่สัมผัสพื้นผิว · จะถูกถ้าทารกอายุ 3 เดือนนอนหงายใช้เครื่องช่วยหายใจใน ICU นานหลายสัปดาห์ ซึ่งท้ายทอยเป็นตำแหน่งแผลกดทับที่พบบ่อยที่สุดในเด็กกลุ่มนี้",
  "D":"Greater trochanter รับน้ำหนักเมื่อนอนตะแคง ลายมือหน้า 59 จัดไว้คู่กับ lateral malleolus และใบหู ซึ่งไม่ใช่จุดลงน้ำหนักหลักขณะนั่งตัวตรงบนรถเข็น · จะถูกถ้าหญิงที่มีแผลผ่าตัดที่หลังจนต้องนอนตะแคงข้างเดียวกันเกือบตลอดวัน และขยับตัวเองไม่ได้",
  "E":"ส้นเท้าเป็นตำแหน่งที่พบบ่อยรองจาก sacrum ในผู้ป่วยนอนหงาย เพราะเนื้อรองบางและน้ำหนักขาทั้งข้างลงที่จุดเล็ก ขณะนั่งรถเข็นเท้าวางบนที่พักเท้าแรงกดไม่สูงเท่าก้น · จะถูกถ้าชายนอนหงายใส่ epidural ระงับปวดหลังผ่าตัดข้อเข่า ขาเหยียดนิ่งบนที่นอน ไม่รู้สึกและยกขาเองไม่ได้"},
 trap="sacrum เป็นคำตอบที่จำได้ก่อนเพราะพบบ่อยที่สุดในผู้ป่วยติดเตียงโดยรวม แต่โจทย์บอกท่านั่ง · วิธีแยก: หาท่าที่ผู้ป่วยอยู่นานที่สุดก่อน แล้วหาปุ่มกระดูกที่รับน้ำหนักในท่านั้น นั่ง = ischial · หงาย = sacrum · ตะแคง = trochanter",
 summary=[
  "แกน: ท่านั่ง → ischial tuberosities · ท่านอนหงาย → sacrum (สไลด์หน้า 59)",
  "ลายมือหน้า 59: ตะแคง → greater trochanter, lateral malleolus, ใบหู",
  "แรงกด: นั่ง ischial ~300 mmHg (ชีทหน้า 6) · หงาย sacrum ~150 mmHg (ชีทหน้า 7)",
  "จุดอื่นในท่าหงาย: ท้ายทอย สะบัก ศอก ส้นเท้า · ในทารกท้ายทอยพบบ่อยที่สุด",
  "ผู้บาดเจ็บไขสันหลังเสี่ยงสูง: ชา · กล้ามเนื้อลีบ · เกร็ง · ผิวเปียกจากกลั้นไม่ได้",
  "ป้องกันในผู้ใช้รถเข็น: เบาะลดแรงกดเฉพาะบุคคล · จัดท่านั่งให้ถูก · ตรวจผิวทุกวัน · จำกัดเวลานั่งเมื่อมีแผล"],
 opinion="เห็นด้วยกับคำตอบ C ความมั่นใจสูง — สไลด์หน้า 59 จับคู่ sitting กับ ischial tuberosities ตรงตัว และชีทหน้า 6 ให้แรงกดขณะนั่งสูงถึง 300 mmHg · ตรงกับ EPUAP/NPIAP/PPPIA 2019 ที่ให้ผู้ใช้รถเข็นใช้เบาะลดแรงกดเฉพาะบุคคลและจำกัดเวลานั่งเมื่อมี ischial pressure injury · ข้อสังเกต: ผู้ที่นั่งเอนไหลลงจนก้นกบรับน้ำหนักแทน (sacral sitting) จะเกิดแผลที่ sacrum หรือ coccyx ได้ ท่าทางการนั่งจึงสำคัญไม่น้อยกว่าระยะเวลา",
 mnemonic="<b>‘นั่ง = Ischial · หงาย = Sacral · ตะแคง = Trochanter’</b>",
 guide="EPUAP/NPIAP/PPPIA Prevention and Treatment of Pressure Ulcers/Injuries: Clinical Practice Guideline, 3rd ed. (2019); Consortium for Spinal Cord Medicine — Pressure Ulcer Prevention and Treatment Following Spinal Cord Injury, 2nd ed. (2014)",
 variants=[
  "ผู้ป่วยใส่สาย NG และหน้ากากออกซิเจนนานหลายวัน → แผลกดทับจากอุปกรณ์ที่ปีกจมูกและหลังใบหู ต้องเปลี่ยนตำแหน่งยึดสายและรองใต้สายทุกวัน",
  "ผู้ใช้รถเข็นที่แขนแข็งแรง → ยกตัวด้วยแขน หรือเอนตัวไปด้านหน้าหรือด้านข้าง เพื่อลดแรงกดที่ก้นเป็นระยะทุก 15–30 นาที ร่วมกับเบาะลดแรงกด",
  "ผู้ป่วย ARDS ที่ต้องนอนคว่ำวันละ 16 ชั่วโมง → แผลกดทับที่หน้าผาก คาง โหนกแก้ม หน้าอก และเข่า ต้องรองนุ่มและหมุนศีรษะเป็นระยะ"])

mk(Q, 56, [59, 's7'],
 stem="A 76-year-old woman with dementia and malnutrition has a deep sacral pressure injury. Which combination of treatments is required?",
 opts=["Systemic corticosteroids","Topical antibiotics alone","Immediate skin grafting without changing her position","Bed rest on her back to protect the wound","Pressure relief, wound care and nutrition"],
 interp="หญิงสูงอายุ สมองเสื่อม ขาดอาหาร มีแผลกดทับลึกที่ก้นกบ → ถามชุดการรักษาที่จำเป็น ต้องใช้หลักสามขาของสไลด์: เอาแรงกดออก ดูแลแผล และเสริมสภาพร่างกายทั้งระบบโดยเฉพาะโภชนาการ ขาดข้อใดแผลก็ไม่หาย",
 why="แผลกดทับหายได้ต้องแก้<b>ทั้งสาเหตุ ตัวแผล และตัวผู้ป่วย</b>พร้อมกัน · <b>Relief of pressure</b>: พลิกตัวเป็นระยะ จัดท่าตะแคง 30° ไม่ให้นอนทับแผล ใช้ที่นอนลดแรงกด และลดแรงเฉือนกับความชื้นจากการกลั้นไม่ได้ · <b>Wound care</b>: ตัดเนื้อตายออก (sharp, enzymatic หรือ autolytic) ทำแผลให้ชุ่มชื้นพอดี จัดการการติดเชื้อเฉพาะที่ และวัดขนาดแผลทุกสัปดาห์ · <b>Systemic enhancement</b>: แก้ภาวะขาดอาหารด้วยพลังงานราว <b>30–35 kcal/kg/วัน</b> และโปรตีน <b>1.25–1.5 g/kg/วัน</b> ร่วมกับคุมน้ำตาล แก้ซีด และรักษาโรคร่วม · ชีทหน้า 7 ย้ำว่าการรักษาที่ดีที่สุดคือป้องกัน แผลตื้นอาจหายเอง แต่แผลลึกอาจต้องผ่าตัดร่วม ซึ่งการผ่าตัด debride และปิดด้วย flap จะได้ผลก็ต่อเมื่อแรงกดและโภชนาการถูกแก้แล้วเท่านั้น · สไลด์หน้า 59 <b>“Treatment: relief of pressure, wound care, systemic enhancement”</b>",
 wrong={
  "A":"Corticosteroid ทั้งตัวกดการอักเสบระยะแรกของการหายของแผล ลดการสร้างคอลลาเจนและหลอดเลือดใหม่ ทำให้ผิวบาง เพิ่มการติดเชื้อ และเพิ่มน้ำตาลในเลือด จึงเป็นปัจจัยที่ทำให้แผลหายช้า · ไม่มีสถานการณ์ใดที่ corticosteroid ทั้งตัวเป็นส่วนของการรักษาแผลกดทับ ถ้าต้องได้ยาจากโรคอื่นยิ่งต้องเข้มเรื่องลดแรงกดและโภชนาการ",
  "B":"ยาปฏิชีวนะทาเฉพาะที่อาจใช้ระยะสั้นเมื่อแผลมีเชื้อมาก แต่ไม่ได้เอาแรงกดที่เป็นสาเหตุออก ไม่ได้ตัดเนื้อตาย และไม่ได้แก้ภาวะขาดอาหาร แผลจึงไม่หาย · ไม่มีสถานการณ์ใดที่ยาปฏิชีวนะทาอย่างเดียวเพียงพอรักษาแผลกดทับลึก เพราะแผลกดทับเป็นแผลจากการขาดเลือดเฉพาะที่ ไม่ใช่การติดเชื้อเป็นหลัก",
  "C":"การปลูกผิวต้องอาศัยพื้นแผลที่มีเลือดเลี้ยงดี สะอาด ไม่มีเนื้อตาย และไม่ถูกกด แผลลึกที่ sacrum มักเป็นโพรงถึงกล้ามเนื้อหรือกระดูก graft บาง ๆ ทนแรงกดไม่ได้ จึงมักต้องใช้ flap · ไม่มีสถานการณ์ใดที่ปลูกผิวบนแผลกดทับแล้วปล่อยให้ผู้ป่วยนอนทับแผลเดิมต่อแล้ว graft จะติด เพราะแรงกดที่เป็นสาเหตุยังอยู่",
  "D":"การนอนหงายคือท่าที่ sacrum รับแรงกดราว 150 mmHg ซึ่งเป็นสาเหตุของแผลนี้เอง การให้นอนหงายพักจึงยิ่งทำให้แผลลึกขึ้น ต้องจัดท่าตะแคงสลับข้างแทน · ไม่มีสถานการณ์ใดที่การนอนหงายทับแผลที่ sacrum ช่วยปกป้องแผล เพราะเพิ่มทั้งแรงกดและแรงเฉือนบนพื้นแผลโดยตรง"},
 trap="คนมักโฟกัสที่ตัวแผล เช่น ยาทาหรือการปลูกผิว แล้วลืมว่าแรงกดและภาวะขาดอาหารเป็นต้นเหตุที่ทำให้แผลไม่หาย · วิธีแยก: คำตอบที่ถูกต้องครบสามขา คือ เอาแรงกดออก ดูแลแผล และเสริมร่างกาย ช้อยที่ขาดขาใดขาหนึ่งไม่ใช่คำตอบ",
 summary=[
  "แกน: รักษา = relief of pressure + wound care + systemic enhancement (สไลด์หน้า 59) · ลายมือ “best = prevent”",
  "Relief of pressure: พลิกตัว · ตะแคง 30° · ที่นอนลดแรงกด · ไม่นอนทับแผล · ลด shear และความชื้น",
  "Wound care: debride เนื้อตาย (sharp, enzymatic, autolytic) · ทำแผลชุ่มชื้นพอดี · คุมการติดเชื้อ",
  "Nutrition (EPUAP 2019): พลังงาน 30–35 kcal/kg/วัน · โปรตีน 1.25–1.5 g/kg/วัน",
  "ชีทหน้า 7: ลดแรงกด + ตัดเนื้อตายและทำแผล + ให้อาหารพอเพียง · แผลตื้นหายเองได้ แผลลึกอาจต้องผ่าตัด",
  "Steroid ทั้งตัว ยาทาอย่างเดียว หรือ graft บนแผลที่ยังถูกกด ไม่ทำให้แผลหาย"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — สไลด์หน้า 59 ระบุ treatment สามข้อ และชีทหน้า 7 ขยายเป็นพลิกตัว ตัดเนื้อตาย ทำแผล และให้อาหารพอเพียง ตรงกับ EPUAP/NPIAP/PPPIA 2019 · ส่วนที่ guideline เพิ่ม: กำหนดพลังงานและโปรตีนเป็นตัวเลขชัด แนะนำอาหารเสริมโปรตีนสูงที่มี arginine และ zinc ในผู้ขาดอาหารที่มีแผลตั้งแต่ระดับ 2 และไม่ควรตัด eschar แห้งแข็งที่ส้นเท้าซึ่งไม่ติดเชื้อ · ผู้ป่วยสมองเสื่อมระยะท้ายควรตั้งเป้าหมายร่วมกับครอบครัว เพราะบางรายเป้าหมายคือความสบายมากกว่าการปิดแผล",
 mnemonic="<b>‘แผลกดทับหาย 3 ขา: ปลดแรงกด · ทำแผล · เติมอาหาร’</b>",
 guide="EPUAP/NPIAP/PPPIA Prevention and Treatment of Pressure Ulcers/Injuries: Clinical Practice Guideline, 3rd ed. (2019); Sabiston Textbook of Surgery 21st ed. (2022) — Plastic surgery, pressure sores",
 variants=[
  "แผลระดับ IV ที่ก้นกบไม่ดีขึ้นหลังลดแรงกด ทำแผล และแก้โภชนาการครบหลายสัปดาห์ → ผ่าตัด debride ตัดปุ่มกระดูก แล้วปิดด้วย gluteal rotation หรือ advancement flap",
  "หญิงติดเตียงมี eschar แห้งแข็งที่ส้นเท้า ไม่แดง ไม่บวม ไม่มีหนอง → ไม่ต้องตัดเนื้อตาย ปล่อยเป็นฝาปิดธรรมชาติ และยกส้นเท้าลอยจากที่นอน",
  "ชายอัมพาตครึ่งล่างอุจจาระราดบ่อยและขาเกร็งมาก รอผ่าตัด flap ปิดแผลที่ sacrum → คุมการขับถ่าย อาจทำ colostomy ชั่วคราว และแก้การเกร็งก่อน มิฉะนั้นแผล flap แยก"])

mk(Q, 57, [60, 's7'],
 stem="An 82-year-old bedbound man has an area over the sacrum with intact skin that remains red and does not blanch for more than an hour after repositioning. What stage is this?",
 opts=["Stage IV","Stage I","Unstageable","Stage III","Stage II"],
 interp="ผู้ป่วยติดเตียงมีผิวที่ก้นกบยังไม่แตก แต่แดง กดไม่ซีด และไม่จางนานกว่า 1 ชั่วโมงหลังพลิกตัว → ถามระดับแผลกดทับ ต้องรู้ว่าระดับแรกนิยามด้วยผิวที่ยังสมบูรณ์แต่แดงค้าง ไม่ต้องมีแผลเปิดก็นับเป็นแผลกดทับแล้ว",
 why="Stage I คือ<b>ผิวยังสมบูรณ์ ไม่มีแผลเปิด แต่มีรอยแดงที่กดแล้วไม่ซีด (non-blanchable erythema)</b> บนปุ่มกระดูก เกิดจากหลอดเลือดฝอยเสียหายและเลือดซึมออกนอกหลอดเลือด ต่างจาก <b>reactive hyperemia</b> ซึ่งแดงจากหลอดเลือดขยายหลังปลดแรงกด กดแล้วซีดและจางไปเองในไม่นาน · ตรวจด้วยการกดนิ้วหรือกดแผ่นใสบนรอยแดง ถ้าสียังคงอยู่ = non-blanchable · สไลด์ใช้เวลา <b>&gt; 1 ชั่วโมง</b>เป็นเกณฑ์ ส่วน NPIAP 2016 ใช้การกดไม่ซีดเป็นหลัก และให้ดูอุณหภูมิ ความแข็ง และอาการปวดร่วม โดยเฉพาะผิวสีเข้มที่เห็นรอยแดงยาก · Stage I เป็นสัญญาณว่าเนื้อลึกอาจเริ่มเสียหายแล้ว ต้องหยุดแรงกดตรงจุดนั้นทันที เพิ่มความถี่การพลิก และใช้ที่นอนลดแรงกด รอยมักหายในไม่กี่วันถ้าปลดแรงกดได้ · สไลด์หน้า 60 <b>“StageI: Skin intact but redden for more than 1 hour”</b>",
 wrong={
  "A":"Stage IV คือแผลเต็มความหนาลึกถึงกระดูกหรือข้อ มักมีโพรงใต้ขอบหรืออุโมงค์ร่วม ต่างจากผิวที่ยังไม่แตกเลยอย่างสิ้นเชิง · จะถูกถ้าชายอัมพาตมีแผลที่ greater trochanter ลึกเป็นโพรงจนเห็นผิวกระดูกต้นขาที่ก้นแผล มีหนองซึมเรื้อรัง",
  "C":"Unstageable คือแผลเต็มความหนาที่ก้นแผลถูกคลุมด้วย slough หรือ eschar จนมองไม่เห็นความลึกจริง ต้องตัดเนื้อตายออกก่อนจึงระบุระดับได้ ไม่ใช่ผิวที่ยังสมบูรณ์ · จะถูกถ้าหญิงติดเตียงมีแผลที่ก้นกบซึ่งพื้นแผลทั้งหมดปกคลุมด้วยเนื้อตายสีเหลืองและสีดำแข็ง มองไม่เห็นพื้นแผลเลย",
  "D":"Stage III คือแผลเต็มความหนาของผิว เห็นชั้นใต้ผิว (สไลด์ให้ทำลายถึงกล้ามเนื้อ) แต่ยังไม่ถึงกระดูก มักมี slough บางส่วน ต้องมีแผลเปิดเสมอ · จะถูกถ้าชายติดเตียงมีแผลที่ก้นกบกว้าง 3 cm ลึกถึงชั้นไขมันใต้ผิว ยังไม่เห็นกระดูกหรือข้อ",
  "E":"Stage II คือผิวหลุดบางส่วนถึงชั้น dermis เห็นพื้นแผลสีชมพูชุ่มชื้น หรือเป็นตุ่มน้ำใสที่ยังสมบูรณ์หรือแตกแล้ว ไม่เห็นไขมัน ผิวจึงไม่สมบูรณ์แล้ว · จะถูกถ้าหญิงติดเตียงมีตุ่มน้ำใสขนาด 2 cm ที่ก้นกบ ผิวรอบตุ่มแดง และใต้ตุ่มเป็นพื้นแผลตื้นสีชมพู"},
 trap="คนมักคิดว่าแผลกดทับต้องมีแผลเปิดจึงจะนับ หรือสับสนกับรอยแดงชั่วคราวหลังพลิกตัว · วิธีแยก: ผิวยังไม่แตก + กดแล้วไม่ซีด + แดงค้างนานกว่า 1 ชั่วโมง = stage I ส่วนรอยที่กดแล้วซีดและจางเร็วเป็นเพียง reactive hyperemia",
 summary=[
  "แกน: Stage I = skin intact + แดงค้าง &gt; 1 ชม. หลังปลดแรงกด (non-blanchable erythema)",
  "ตรวจ: กดนิ้วหรือแผ่นใส ถ้าสีไม่ซีด = stage I · ซีดและจางเร็ว = reactive hyperemia",
  "ผิวสีเข้ม: ใช้ความอุ่น ความแข็ง อาการบวม และปวดช่วยตัดสินแทนสี",
  "ลำดับในสไลด์หน้า 60: I แดงค้าง · II blister or break in dermis · III ถึงกล้ามเนื้อ · IV ถึงกระดูกหรือข้อ",
  "รูปสไลด์หน้า 60: จุดกดในท่าหงาย ท้ายทอย สะบัก ศอก sacrum ส้นเท้า",
  "จัดการ stage I: ปลดแรงกดจุดนั้นทันที · พลิกถี่ขึ้น · ที่นอนลดแรงกด · รักษาผิวให้แห้งสะอาด"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — สไลด์หน้า 60 นิยาม stage I ด้วยผิวสมบูรณ์และแดงเกิน 1 ชั่วโมงตรงตามโจทย์ และรูป stage1 ในชีทหน้า 7 เป็นผิวแดงคล้ำไม่มีแผลเปิด · จุดที่ต่างจาก NPIAP 2016: ระบบปัจจุบันไม่ใช้ตัวเลขเวลา แต่ใช้ non-blanchable erythema และระบุว่าถ้าสีม่วงคล้ำหรือแดงเข้มอมม่วงให้จัดเป็น deep tissue pressure injury แทน ทั้งเปลี่ยนชื่อจาก pressure ulcer เป็น pressure injury และใช้เลขอารบิก stage 1–4",
 mnemonic="<b>‘I = Intact + แดงไม่จาง &gt; 1 ชม.’</b>",
 guide="NPIAP Pressure Injury Stages (revised 2016); EPUAP/NPIAP/PPPIA Prevention and Treatment of Pressure Ulcers/Injuries: Clinical Practice Guideline, 3rd ed. (2019)",
 variants=[
  "ชายผิวคล้ำติดเตียง รอยแดงที่ก้นกบเห็นไม่ชัด แต่คลำอุ่นกว่าผิวรอบ แข็ง และกดเจ็บ → สงสัย stage 1 ใช้อาการเหล่านี้แทนสีผิว",
  "หญิงที่นอนตะแคงซ้ายเป็นหลักมีรอยแดงกดไม่ซีดที่ใบหูซ้าย ผิวยังไม่แตก → stage 1 ที่ใบหู เปลี่ยนข้างนอนและใช้หมอนเว้นช่องใบหู",
  "ผู้ป่วยใส่ท่อช่วยหายใจมีแผลที่เยื่อบุริมฝีปากใต้ท่อ → mucosal membrane pressure injury ไม่จัด stage เพราะเยื่อบุไม่มีชั้นแบบผิวหนัง"])

mk(Q, 58, [60, 's7'],
 stem="A 70-year-old woman has a sacral pressure injury in which bone is exposed at the base. What stage is this?",
 opts=["Stage IV","Stage II","Stage III","Deep tissue injury","Stage I"],
 interp="แผลกดทับที่ก้นกบลึกจนเห็นกระดูกที่พื้นแผล → ถามระดับ ต้องรู้ว่าระดับตัดสินด้วยชั้นเนื้อเยื่อที่ลึกที่สุดที่ถูกทำลายหรือมองเห็นได้ ไม่ใช่ขนาดความกว้างของแผล และการเห็นกระดูกหรือข้อคือระดับสูงสุด",
 why="การแบ่งระดับแผลกดทับใช้<b>ความลึกของเนื้อเยื่อที่เสียหาย</b>เป็นเกณฑ์: I ผิวสมบูรณ์แดงค้าง · II ผิวหลุดบางส่วนถึง dermis หรือตุ่มพอง · III เต็มความหนาผิวลงถึงชั้นใต้ผิว · <b>IV ถึงกระดูกหรือข้อ</b> โดย NPIAP รวมกล้ามเนื้อ เอ็น กระดูกอ่อน และกระดูกที่มองเห็นหรือคลำได้ไว้ใน stage 4 ทั้งหมด · แผลระดับ IV มักมีโพรงใต้ขอบ (undermining) และอุโมงค์ (tunneling) จึงต้องวัดความลึกด้วย probe · ความเสี่ยงสำคัญคือ <b>osteomyelitis</b> ของกระดูกใต้แผล ซึ่งยืนยันด้วย bone biopsy ส่ง culture และพยาธิ ส่วน MRI ช่วยดูขอบเขต · แผลระดับนี้แทบไม่หายเองด้วยการทำแผลอย่างเดียว ต้อง debride เนื้อตายและกระดูกที่ติดเชื้อ แล้วปิดด้วย musculocutaneous หรือ fasciocutaneous flap เมื่อปลดแรงกด โภชนาการ และความชื้นพร้อมแล้ว · แผลที่กำลังหายยังเรียก healing stage 4 ไม่ลดระดับย้อนกลับ · สไลด์หน้า 60 <b>“StageIV: Involvement of bone or joint”</b>",
 wrong={
  "B":"Stage II คือผิวหลุดบางส่วนถึงชั้น dermis หรือเป็นตุ่มพอง พื้นแผลสีชมพูชุ่มชื้น ไม่เห็นไขมันหรือเนื้อเยื่อที่ลึกกว่า จึงห่างไกลจากแผลที่เห็นกระดูก · จะถูกถ้าชายติดเตียงมีผิวถลอกตื้นสีชมพูขนาด 1.5 cm ที่ก้นกบ ขอบแผลเรียบ ไม่มีเนื้อตายและไม่เห็นไขมัน",
  "C":"Stage III คือแผลเต็มความหนาของผิวลงถึงชั้นใต้ผิว สไลด์ระบุทำลายถึงกล้ามเนื้อ แต่ยังไม่ถึงกระดูกหรือข้อ ซึ่งเป็นเส้นแบ่งกับ stage IV · จะถูกถ้าหญิงมีแผลที่ greater trochanter เป็นหลุมลึกเห็นไขมันใต้ผิวที่พื้นแผล ขอบแผลม้วน แต่ไม่เห็นและคลำไม่ถึงกระดูก",
  "D":"Deep tissue pressure injury คือผิวยังไม่แตกหรือเป็นตุ่มเลือด มีสีม่วงคล้ำหรือแดงเข้มอมม่วงที่กดไม่ซีด เพราะเนื้อลึกใกล้กระดูกบาดเจ็บก่อนผิว ยังไม่มีแผลเปิดให้เห็นกระดูก · จะถูกถ้าชายที่หมดสตินอนบนพื้นนาน 12 ชั่วโมง มีปื้นสีม่วงคล้ำที่ก้นกบ ผิวยังไม่แตกและกดไม่ซีด",
  "E":"Stage I คือผิวยังสมบูรณ์ ไม่มีแผลเปิด มีเพียงรอยแดงที่กดไม่ซีดค้างเกิน 1 ชั่วโมงหลังปลดแรงกด จึงไม่มีทางเห็นกระดูกได้ · จะถูกถ้าหญิงติดเตียงมีรอยแดงกดไม่ซีดที่ส้นเท้า ผิวยังไม่แตก และยังแดงอยู่เกิน 1 ชั่วโมงหลังยกส้นเท้าลอยจากที่นอน"},
 trap="แผลที่เห็นกระดูกบางรายมีปากแผลเล็กจนดูเหมือนแผลตื้น เพราะโพรงอยู่ใต้ขอบ หรือคนสับสนว่าเนื้อลึกเป็นระดับ III ตามสไลด์ · วิธีแยก: ตัดสินจากชั้นที่ลึกที่สุดที่มองเห็นหรือคลำได้ เห็นหรือคลำถึงกระดูกหรือข้อ = IV เสมอ ไม่ว่าแผลกว้างแค่ไหน",
 summary=[
  "แกน: เห็นหรือคลำถึงกระดูกหรือข้อ = Stage IV (สไลด์หน้า 60) ตัดสินจากความลึก ไม่ใช่ความกว้าง",
  "NPIAP 2016: stage 4 รวมกล้ามเนื้อ เอ็น กระดูกอ่อน หรือกระดูกที่เห็นหรือคลำได้ · สไลด์จัดกล้ามเนื้อไว้ใน III",
  "NPIAP เพิ่มหมวด unstageable (slough หรือ eschar คลุม) และ deep tissue pressure injury (ม่วงคล้ำ ผิวไม่แตก)",
  "Stage IV มักมี undermining และ tunneling · วัดความลึกด้วย probe",
  "สงสัย osteomyelitis → bone biopsy เป็นมาตรฐาน ± MRI",
  "รักษา: debride + ตัดกระดูกที่ติดเชื้อ → flap เมื่อปลดแรงกดและโภชนาการพร้อม"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — สไลด์หน้า 60 ให้ Stage IV = involvement of bone or joint ตรงกับโจทย์ และรูป stage4 ในชีทหน้า 7 เป็นแผลโพรงลึกกว้าง · จุดที่สไลด์ต่างจาก NPIAP 2016: สไลด์จัดการทำลายถึงกล้ามเนื้อเป็น stage III ขณะที่ NPIAP ถือว่าเห็นกล้ามเนื้อ เอ็น หรือกระดูกเป็น stage 4 ทั้งหมด และ stage 3 ลึกได้เพียงชั้นไขมัน · สไลด์ยังไม่มีหมวด unstageable และ deep tissue pressure injury ซึ่งเป็นส่วนของระบบปัจจุบันที่ควรรู้คู่กัน",
 mnemonic="<b>‘IV = เห็น Bone หรือ Joint · ลึกสุดตัดสิน ไม่ใช่กว้างสุด’</b>",
 guide="NPIAP Pressure Injury Stages (revised 2016); EPUAP/NPIAP/PPPIA Prevention and Treatment of Pressure Ulcers/Injuries: Clinical Practice Guideline, 3rd ed. (2019); Grabb and Smith's Plastic Surgery 8th ed. (2020) — Pressure sores",
 variants=[
  "แผลระดับ IV ที่ก้นกบปิดสนิทด้วย flap แล้ว 1 ปีต่อมาผิวแผลเป็นแตกเป็นแผลตื้น → ยังจัดเป็น stage 4 ที่กลับเป็นซ้ำ ไม่จัดเป็น stage 2",
  "แผลลึกเห็นกระดูกที่ก้นกบมีกลิ่นเหม็นและเนื้อตายเป็นแผ่น ผู้ป่วยไข้สูงความดันต่ำ → sepsis จากแผล ต้อง sharp debridement ด่วนร่วมกับยาปฏิชีวนะทางหลอดเลือด",
  "แผลกดทับเรื้อรังนานหลายปีที่ขอบแผลนูนแข็ง ม้วนออก และเลือดออกง่าย → สงสัย Marjolin ulcer ชนิด SCC ตัดชิ้นเนื้อจากขอบแผลส่งตรวจ"])

mk(Q, 59, [61, 's8', 's9'],
 stem="A 30-year-old man has a hot, red, spreading plaque on his leg. Culture grows beta-hemolytic gram-positive cocci in chains, Lancefield group A. Which organism is this?",
 opts=["Pox virus","Staphylococcus aureus","Streptococcus agalactiae","Streptococcus pyogenes","Human papillomavirus"],
 interp="ผิวแดงร้อนลามที่ขา เพาะเชื้อได้ gram-positive cocci เรียงเป็นสาย มี beta-hemolysis และจัดเป็น Lancefield group A → ถามชื่อเชื้อ ต้องแปลงกลุ่ม Lancefield เป็นชื่อสปีชีส์ และแยกจาก streptococcus กลุ่มอื่น staphylococcus และไวรัสก่อโรคผิวหนัง",
 why="<b>Streptococcus pyogenes</b> คือ <b>group A beta-hemolytic streptococcus (GAS)</b>: gram-positive cocci เรียงเป็นสาย สลายเม็ดเลือดแดงสมบูรณ์บน blood agar (beta-hemolysis) catalase negative ไวต่อ bacitracin และจัดกลุ่มด้วย carbohydrate antigen ที่ผนังเซลล์ตามระบบ Lancefield · ต่างจาก <b>S. agalactiae</b> ซึ่งเป็น group B และ <b>S. aureus</b> ซึ่งเรียงเป็นกลุ่มองุ่น catalase และ coagulase positive ไม่มี Lancefield group · GAS เป็นสาเหตุหลักของ <b>cellulitis ชนิดไม่มีหนองและ erysipelas</b> ทั้งยังก่อ impetigo, necrotizing fasciitis ชนิดเชื้อเดี่ยว และ streptococcal toxic shock syndrome · เชื้อยังไวต่อ penicillin ทุกสายพันธุ์ จึงใช้ penicillin หรือ cephalexin ส่วนรายรุนแรงให้ clindamycin ร่วมเพื่อยับยั้งการสร้าง toxin · ภาวะแทรกซ้อนหลังติดเชื้อที่ผิวที่ควรรู้คือ post-streptococcal glomerulonephritis · สไลด์หน้า 61 <b>“Streptococcus pyogenes [ beta-haemolytic Streptococcus Lancefield group A]”</b>",
 wrong={
  "A":"Poxvirus เป็นไวรัส DNA ขนาดใหญ่ ทำให้เกิด molluscum contagiosum เป็นตุ่มนูนมันวาวมีรอยบุ๋มตรงกลาง ไม่ใช่แบคทีเรียและเพาะบน blood agar ไม่ขึ้น · จะถูกถ้าเด็กอายุ 5 ปีมีตุ่มนูนสีเนื้อมันวาวขนาด 3 mm หลายตุ่มที่ลำตัว ตรงกลางบุ๋ม บีบแล้วมีเนื้อขาวคล้ายขี้ผึ้งออกมา",
  "B":"S. aureus เป็น gram-positive cocci เรียงเป็นกลุ่มคล้ายพวงองุ่น catalase และ coagulase positive ไม่มี Lancefield antigen และเป็นสาเหตุหลักของการติดเชื้อที่มีหนอง เช่น folliculitis furuncle carbuncle และฝี · จะถูกถ้าชายมีฝีเป็นก้อน fluctuant ที่ต้นขา หนองเพาะได้ gram-positive cocci เรียงเป็นกลุ่ม coagulase positive",
  "C":"S. agalactiae เป็น beta-hemolytic streptococcus เช่นกัน แต่จัดเป็น Lancefield group B พบในลำไส้และช่องคลอด ก่อโรคในทารกแรกเกิด และในผู้ใหญ่เบาหวานหรือผู้สูงอายุ เช่น cellulitis และแผลเบาหวาน · จะถูกถ้าชายเบาหวานมี cellulitis ที่เท้า เพาะเชื้อได้ beta-hemolytic streptococcus ที่จัดกลุ่ม Lancefield เป็น group B",
  "E":"HPV เป็นไวรัส DNA ที่ติดเชื้อ keratinocyte ทำให้เกิดหูด ไม่ใช่แบคทีเรีย เพาะบน blood agar ไม่ได้ และไม่ทำให้เกิดการอักเสบแดงร้อนลาม · จะถูกถ้าเด็กอายุ 12 ปีมีตุ่มนูนผิวขรุขระสีเนื้อหลายตุ่มที่นิ้วมือ มีจุดดำเล็กตรงกลางจากหลอดเลือดฝอยอุดตัน"},
 trap="S. aureus และ S. pyogenes อยู่คู่กันบนสไลด์จึงสลับกันง่าย และ group B ก็เป็น beta-hemolytic เหมือนกัน · วิธีแยก: Lancefield ใช้จัดกลุ่มเฉพาะ streptococcus · group A = pyogenes · group B = agalactiae · staphylococcus เรียงเป็นกลุ่มองุ่นและไม่มี Lancefield group",
 summary=[
  "แกน: beta-hemolytic Streptococcus Lancefield group A = Streptococcus pyogenes (สไลด์หน้า 61)",
  "สไลด์หน้า 61: แบคทีเรีย S. aureus + S. pyogenes · ไวรัส HPV · poxvirus · herpesvirus",
  "ชีทหน้า 8: cellulitis เชื้อที่พบบ่อยที่สุดคือ group A streptococci และ S. aureus · ยากินพอ ยกเว้นภูมิคุ้มกันผิดปกติให้ทางหลอดเลือด",
  "ไม่มีหนอง (cellulitis, erysipelas) → คิด GAS · มีหนอง (ฝี furuncle) → คิด S. aureus (IDSA 2014)",
  "ชีทหน้า 9: necrotizing soft tissue infection มักเป็นเชื้อผสม มี group A streptococci อยู่ในรายการ",
  "Lab: GAS เรียงเป็นสาย · catalase negative · bacitracin sensitive · S. aureus เป็นกลุ่ม · catalase และ coagulase positive"],
 opinion="เห็นด้วยกับคำตอบ D ความมั่นใจสูง — สไลด์หน้า 61 เขียนไว้ตรงตัวว่า Streptococcus pyogenes คือ beta-haemolytic Streptococcus Lancefield group A · ชีทหน้า 8 ระบุ group A streptococci และ S. aureus เป็นเชื้อหลักของ cellulitis ซึ่งยังตรงกับ IDSA 2014 ที่แยกต่อว่า cellulitis ไม่มีหนองเกิดจาก streptococcus เป็นส่วนใหญ่ ส่วนชนิดมีหนองให้ครอบคลุม S. aureus · สิ่งที่สไลด์ไม่ได้บอกแต่ควรรู้คือ GAS ยังไวต่อ penicillin ทุกสายพันธุ์ cellulitis ไม่มีหนองที่ไม่รุนแรงจึงไม่จำเป็นต้องใช้ยาครอบคลุม MRSA",
 mnemonic="<b>‘A = pyogenes · B = Baby (agalactiae) · Staph = พวงองุ่น ไม่มี Lancefield’</b>",
 guide="IDSA Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections (Clin Infect Dis 2014;59:e10–52); Sabiston Textbook of Surgery 21st ed. (2022) — Surgical infections",
 variants=[
  "หญิงมีผื่นแดงนูนขอบชัดยกตัวจากผิวรอบที่แก้ม ไข้สูงหนาวสั่น → erysipelas จาก S. pyogenes ให้ penicillin",
  "เด็กมีแผลตกสะเก็ดสีน้ำผึ้งรอบจมูก 3 สัปดาห์ต่อมามีปัสสาวะสีโคล่าและหนังตาบวม → post-streptococcal glomerulonephritis ตามหลังการติดเชื้อ GAS ที่ผิวหนัง",
  "ชาย necrotizing fasciitis เพาะได้ GAS อย่างเดียว ร่วมกับช็อกและไตวายเฉียบพลัน → streptococcal toxic shock syndrome ผ่าตัด debride ด่วน ให้ penicillin ร่วมกับ clindamycin"])

mk(Q, 60, [62, 63, 64, 's7'],
 stem="A 25-year-old man has a few small pustules centered on hair follicles in the beard area, without fever. What is the most appropriate management?",
 opts=["Radiotherapy","Wide surgical debridement","Intravenous vancomycin","Incision and drainage of each pustule under local anesthesia","Skin hygiene and observation"],
 interp="ชายวัยหนุ่มมีตุ่มหนองเล็กไม่กี่ตุ่มตรงรูขุมขนบริเวณหนวด ไม่มีไข้ ไม่มีก้อน fluctuant = folliculitis ระดับเล็กน้อย → ถามการจัดการที่เหมาะสม ต้องรู้ว่าเป็นการติดเชื้อตื้นที่สุดของรูขุมขน ส่วนใหญ่หายเองด้วยการดูแลความสะอาด",
 why="<b>Folliculitis</b> คือการติดเชื้อตื้นที่ปากรูขุมขน เห็นเป็น<b>ตุ่มหนองเล็กมีเส้นขนอยู่ตรงกลางบนฐานแดง</b> เจ็บเล็กน้อย มักเกิดตรงที่มีขนและถูกเสียดสีหรือโกน เช่น หนวด รักแร้ ขา ก้น · เชื้อหลักคือ <b>S. aureus</b> บางครั้งเป็น gram-negative เช่น Pseudomonas จากอ่างน้ำร้อน · เพราะการอักเสบอยู่ตื้นและยังไม่เป็นโพรงหนอง ราย<b>ไม่กี่ตุ่มที่ไม่มีไข้จึงหายเองได้</b>ด้วยการล้างผิวด้วยสบู่ฆ่าเชื้อ ประคบอุ่น หยุดโกนหรือเปลี่ยนวิธีโกนชั่วคราว ± ยาทา mupirocin · ให้<b>ยากินกลุ่ม anti-staphylococcal</b> เช่น dicloxacillin หรือ cephalexin เมื่อเป็นหลายตุ่มกระจายกว้างหรือไม่ดีขึ้น · ถ้าตุ่มลึกลงเป็นก้อน fluctuant กลายเป็น furuncle หรือ carbuncle จึงต้องผ่าระบาย · สไลด์หน้า 62 ลายมือ <b>“เป็นน้อยๆ อาจจะหายเอง · หลายเม็ด → oral dicloxacillin”</b>",
 wrong={
  "A":"การฉายรังสีใช้รักษามะเร็งและภาวะเฉพาะบางอย่าง ไม่มีฤทธิ์ฆ่าเชื้อ และทำให้ผิวบาง เกิดพังผืดและแผลเรื้อรังในระยะยาว ซึ่งรุนแรงกว่าตุ่มหนองที่หายเองได้หลายเท่า · ไม่มีสถานการณ์ใดที่แนวทางปัจจุบันใช้รังสีรักษา folliculitis จากแบคทีเรีย เพราะการดูแลผิว ยาทา และยากินให้ผลดีโดยไม่มีผลเสียระยะยาว",
  "B":"การตัดเนื้อตายกว้างเป็นการรักษาหลักของ necrotizing soft tissue infection ที่เชื้อลามตามชั้น fascia ผู้ป่วยมักปวดมากเกินผิวที่เห็น มีไข้และช็อก ห่างไกลจากตุ่มหนองตื้นไม่กี่ตุ่ม · จะถูกถ้าชายเบาหวานมีขาบวมแดงลามเร็ว ปวดมากกว่าที่เห็น มีตุ่มน้ำเลือดและความดันต่ำ ซึ่งการจัดการที่เหมาะสมที่สุดคือผ่าตัด debride กว้างโดยด่วน",
  "C":"Vancomycin ทางหลอดเลือดใช้กับการติดเชื้อผิวหนังรุนแรงที่สงสัย MRSA เช่นฝีหรือ cellulitis ที่มี SIRS ภูมิคุ้มกันบกพร่อง หรือไม่ตอบสนองต่อยากิน จึงเกินความจำเป็นมากสำหรับตุ่มเล็กที่ไม่มีไข้ · จะถูกถ้าชายฟอกไตที่เคยติดเชื้อ MRSA มี carbuncle ที่หลังร่วมกับไข้สูง หัวใจเต้นเร็ว และเม็ดเลือดขาวสูง ซึ่งต้องได้ vancomycin ร่วมกับผ่าระบาย",
  "D":"การผ่าระบายหนองใช้กับโพรงหนองที่คลำได้ fluctuant เช่น furuncle carbuncle หรือฝี ตุ่มหนองของ folliculitis เล็กและตื้นที่ปากรูขุมขน แตกและแห้งเองโดยไม่ต้องผ่า การกรีดทีละตุ่มเพิ่มแผลเป็นและความเจ็บโดยไม่จำเป็น · ไม่มีสถานการณ์ใดที่ต้องผ่าระบายตุ่มหนองเล็กของ folliculitis ทีละตุ่ม เพราะตุ่มเหล่านี้ไม่มีโพรงหนองให้ระบาย"},
 trap="คำว่า pustule ชวนให้คิดถึงหนองที่ต้องผ่าระบาย หรือคิดว่าการติดเชื้อทุกชนิดต้องให้ยาปฏิชีวนะ · วิธีแยก: ตุ่มเล็กตื้นที่รูขุมขน ไม่มีก้อน fluctuant ไม่มีไข้ = folliculitis ระดับน้อย ดูแลความสะอาดและเฝ้าดู ส่วนก้อนที่คลำได้ fluctuant จึงผ่าระบาย",
 summary=[
  "แกน: folliculitis ไม่กี่ตุ่ม ไม่มีไข้ → ดูแลความสะอาดและเฝ้าดู (ลายมือหน้า 62: เป็นน้อยๆ อาจจะหายเอง)",
  "ลายมือหน้า 62: ตำแหน่งที่พบ หนวด รักแร้ · “ตุ่มเจ็บ” · หลายเม็ด → oral dicloxacillin",
  "ชีทหน้า 7: เชื้อมักเป็น Staphylococcus บางครั้ง gram-negative · ทำความสะอาดผิวแล้วจะค่อยๆ ดีขึ้น",
  "ลำดับความลึก: folliculitis (ปากรูขุมขน) → furuncle (ฝีรอบรูขุมขนเดียว) → carbuncle (หลาย furuncle เชื่อมกัน หลายหัว)",
  "ชีทหน้า 7: furuncle ประคบน้ำอุ่นให้หนองไหลออก บางครั้งต้องให้ยาร่วม · ก้อนใหญ่ carbuncle และฝี → I&amp;D",
  "ยาทาทางเลือก: mupirocin · ยากิน: dicloxacillin หรือ cephalexin"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ลายมือสไลด์หน้า 62 ระบุว่าเป็นน้อย ๆ อาจหายเอง และชีทหน้า 7 ให้ทำความสะอาดผิวแล้วจะค่อย ๆ ดีขึ้น ตรงกับตำรามาตรฐานที่ให้การดูแลเฉพาะที่ ± ยาทาสำหรับรายไม่รุนแรง · ส่วนที่ต่างเล็กน้อย: ลายมือเลือก dicloxacillin สำหรับรายหลายเม็ด ซึ่งยังใช้ได้ แต่ในทางปฏิบัติ cephalexin ใช้แทนได้และกินง่ายกว่า และ IDSA 2014 แนะนำให้รายที่เป็นฝีหรือตุ่มหนองซ้ำบ่อยค้นหาและกำจัดเชื้อ S. aureus ที่โพรงจมูก",
 mnemonic="<b>‘ตุ่มเล็กไม่ไข้ = ล้างแล้วรอ · หลายเม็ด = Dicloxacillin · คลำได้ fluctuant = กรีด’</b>",
 guide="IDSA Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections (Clin Infect Dis 2014;59:e10–52); Fitzpatrick's Dermatology 9th ed. (2019) — Superficial cutaneous infections",
 variants=[
  "ชายมีตุ่มหนองตรงรูขุมขนกระจายทั่วลำตัวหลังแช่อ่างน้ำร้อนในโรงแรม 2 วันก่อน → hot tub folliculitis จาก Pseudomonas aeruginosa ส่วนใหญ่หายเองใน 1–2 สัปดาห์",
  "ชายขนหยิกมีตุ่มแดงเจ็บที่คางหลังโกนหนวดชิดทุกครั้ง เพาะเชื้อไม่ขึ้น → pseudofolliculitis barbae จากขนม้วนกลับแทงผิว แนะนำหยุดโกนชิดหรือใช้ปัตตาเลี่ยน",
  "ผู้ป่วยสิวที่กิน tetracycline นานหลายเดือน มีตุ่มหนองรอบจมูกและคางมากขึ้น → gram-negative folliculitis หยุดยาเดิมและพิจารณา isotretinoin"])

